"""Generated by AetherLab (deterministic pendulum template)."""

import math

import numpy as np

from manim import *

config.background_color = "#0A0A0F"


class F146MathScene(Scene):
    def construct(self):
        TXT = '#F8FAFC'
        title = Text('Маятник: исследуем движение', color=TXT).scale(0.42).to_edge(UP)
        eqn = Text('При отклонении маятник начинает двигаться.', color='#F59E0B').scale(0.42)
        eqn.next_to(title, DOWN, buff=0.35)
        box = SurroundingRectangle(eqn, color='#06B6D4', buff=0.22, corner_radius=0.1)
        self.play(Write(title), run_time=0.6)
        self.play(FadeIn(eqn), Create(box), run_time=1.0)

        g = 9.81
        length = 1.0
        damping = 0.12
        omega = math.sqrt(g / length)
        theta0 = 0.9

        pivot = np.array([-3.2, -0.4, 0.0])
        rod_len = 1.9
        t = ValueTracker(0.0)

        def theta_at(time):
            return theta0 * math.exp(-damping * time) * math.cos(omega * time)

        def bob_pos():
            th = theta_at(t.get_value())
            return pivot + rod_len * np.array([math.sin(th), -math.cos(th), 0.0])

        rod = always_redraw(lambda: Line(pivot, bob_pos(), color='#94A3B8', stroke_width=3))
        bob = always_redraw(lambda: Dot(bob_pos(), color='#F59E0B', radius=0.14))
        anchor = Dot(pivot, color=TXT, radius=0.05)

        axes = Axes(x_range=[0, 8, 2], y_range=[-1, 1, 0.5]).scale(0.42)
        axes.to_edge(DOWN).shift(RIGHT * 1.8)

        def trace_fn():
            end = max(t.get_value(), 0.01)
            fn = lambda x: theta_at(x)
            if hasattr(axes, "plot"):
                return axes.plot(fn, x_range=[0, end], color='#10B981')
            return axes.get_graph(fn, x_min=0, x_max=end, color='#10B981')

        trace = always_redraw(trace_fn)
        label = Text("theta(t)", color=TXT).scale(0.3)
        label.next_to(axes, UP, buff=0.1)

        self.add(anchor, rod, bob, axes, trace, label)
        self.play(t.animate.set_value(8.0), run_time=5.10, rate_func=linear)
        self.wait(0.5)
